    private final Room deluxe = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));

    private static ErrorCode errorOf(Runnable action) {
        return org.junit.jupiter.api.Assertions.assertThrows(HotelException.class, action::run).errorCode();
    }

    \@Test
    void corporatePlanDiscountDependsOnTheCompany() {
        LocalDate in = LocalDate.of(2027, 3, 10);
        LocalDate out = LocalDate.of(2027, 3, 12);

        Price tecnosul = calculator.calculate(deluxe, in, out, RatePlan.CORPORATE, "TECNOSUL");
        assertEquals(new BigDecimal("779.80"), tecnosul.subtotal());
        assertEquals(new BigDecimal("93.58"), tecnosul.discount());
        assertEquals(new BigDecimal("686.22"), tecnosul.total());
        assertEquals(new BigDecimal("639.44"), calculator.calculate(deluxe, in, out, RatePlan.CORPORATE, "AGROVALE").total());
        assertEquals(new BigDecimal("584.85"), calculator.calculate(deluxe, in, out, RatePlan.CORPORATE, "FARMAVIDA").total());
    }

    \@Test
    void corporatePlanNeedsAKnownCompanyCode() {
        LocalDate in = LocalDate.of(2027, 3, 10);
        LocalDate out = LocalDate.of(2027, 3, 12);

        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(deluxe, in, out, RatePlan.CORPORATE, null)));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(deluxe, in, out, RatePlan.CORPORATE, "ACME")));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(deluxe, in, out, RatePlan.CORPORATE, "tecnosul")));
    }

    \@Test
    void otherPlansIgnoreTheCompanyCode() {
        Price price = calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 11), RatePlan.STANDARD, "TECNOSUL");
        assertEquals(new BigDecimal("249.90"), price.total());
    }

    \@Test
    void weekendPackageIsAClosedPriceEvenInHighSeason() {
        Price deluxePrice = calculator.calculate(
                deluxe, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14), RatePlan.WEEKEND_PACKAGE, null);
        assertEquals(2, deluxePrice.nights());
        assertEquals(new BigDecimal("820.00"), deluxePrice.subtotal());
        assertEquals(new BigDecimal("0.00"), deluxePrice.discount());
        assertEquals(new BigDecimal("820.00"), deluxePrice.total());

        // 2027-01-08 is a Friday, in high season
        assertEquals(new BigDecimal("520.00"), calculator.calculate(
                standardRoom, LocalDate.of(2027, 1, 8), LocalDate.of(2027, 1, 10), RatePlan.WEEKEND_PACKAGE, null).total());
        assertEquals(new BigDecimal("1200.00"), calculator.calculate(
                suite, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14), RatePlan.WEEKEND_PACKAGE, null).total());
    }

    \@Test
    void weekendPackageOnlyFromFridayToSunday() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                deluxe, LocalDate.of(2027, 3, 11), LocalDate.of(2027, 3, 13), RatePlan.WEEKEND_PACKAGE, null)));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                deluxe, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 15), RatePlan.WEEKEND_PACKAGE, null)));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                deluxe, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 13), RatePlan.WEEKEND_PACKAGE, null)));
    }

    \@Test
    void longStayGivesTenPercentFromSevenNights() {
        Price price = calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 8), RatePlan.LONG_STAY, null);
        assertEquals(new BigDecimal("1749.30"), price.subtotal());
        assertEquals(new BigDecimal("174.93"), price.discount());
        assertEquals(new BigDecimal("1574.37"), price.total());

        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 7), RatePlan.LONG_STAY, null)));
    }

    \@Test
    void longStayKeepsTheHighSeasonSurcharge() {
        // 7 nights from 2027-02-25: 4 in February (high season) and 3 in March
        Price price = calculator.calculate(
                standardRoom, LocalDate.of(2027, 2, 25), LocalDate.of(2027, 3, 4), RatePlan.LONG_STAY, null);
        // 3 nights of 249.90 + 4 nights of 299.88
        assertEquals(new BigDecimal("1949.22"), price.subtotal());
    }
}
