    \@Test
    void cancellingGivesBackWhatTheNewPlansSay() {
        Guest guest = new Guest("Ana Souza", "ana\@example.com", "123.456.789-09");
        Reservation weekend = service.create(new NewReservation(
                201, guest, LocalDate.parse("2027-03-12"), LocalDate.parse("2027-03-14"), 2, RatePlan.WEEKEND_PACKAGE));
        Reservation corporate = service.create(new NewReservation(
                202, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2, RatePlan.CORPORATE,
                "TECNOSUL"));
        Reservation longStay = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));
        service.confirm(weekend.id());
        service.confirm(corporate.id());
        service.confirm(longStay.id());

        assertEquals(new BigDecimal("410.00"), service.cancel(weekend.id()).refund());
        assertEquals(new BigDecimal("686.22"), service.cancel(corporate.id()).refund());
        assertEquals(new BigDecimal("1574.37"), service.cancel(longStay.id()).refund());
    }

    \@Test
    void aReservationBrokingThePlanRulesIsInvalid() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 2, RatePlan.LONG_STAY))));
    }
}
