    \@Test
    void takesTheCompanyCodeAndRejectsPlansBrokenByTheirRules() throws Exception {
        String corporate = RESERVATION_JSON.replace("STANDARD", "CORPORATE").replace("2027-07-10", "2027-03-10")
                .replace("2027-07-12", "2027-03-12");

        HttpResponse<String> withoutCode = post("\/reservations", corporate);
        assertEquals(400, withoutCode.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(withoutCode.body()).get("error").asText());

        HttpResponse<String> created =
                post("\/reservations", corporate.replace("\\"guests\\"", "\\"companyCode\\": \\"TECNOSUL\\", \\"guests\\""));
        assertEquals(201, created.statusCode());
        assertEquals(686.22, json.readTree(created.body()).get("total").asDouble());

        String ignoredCode = RESERVATION_JSON.replace("\\"guests\\"", "\\"companyCode\\": \\"ACME\\", \\"guests\\"");
        assertEquals(201, post("\/reservations", ignoredCode).statusCode());
    }
}
